import 'package:flutter/material.dart';import '../../core/data/device_repository.dart';import '../../shared/irkop_ui.dart';
class DevicesPage extends StatefulWidget{const DevicesPage({super.key,this.businessId});final String? businessId;@override State<DevicesPage> createState()=>_S();}class _S extends State<DevicesPage>{final r=DeviceRepository();late Future<List<DeviceRecord>> f;@override void initState(){super.initState();f=load();}Future<List<DeviceRecord>> load()=>widget.businessId==null?Future.value(const[]):r.load(widget.businessId!);Future<void> refresh()async{setState(()=>f=load());await f;}Future<void> add()async{final b=widget.businessId;if(b==null)return;final n=TextEditingController(),c=TextEditingController();final ok=await showModalBottomSheet<bool>(context:context,builder:(x)=>Padding(padding:const EdgeInsets.all(16),child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Nama perangkat')),TextField(controller:c,decoration:const InputDecoration(labelText:'Kode perangkat')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Simpan'))])));if(ok==true&&n.text.isNotEmpty&&c.text.isNotEmpty){await r.create(businessId:b,name:n.text,code:c.text);await refresh();}}@override Widget build(BuildContext c)=>RefreshIndicator(onRefresh:refresh,child:FutureBuilder<List<DeviceRecord>>(future:f,builder:(c,s)=>ListView(padding:const EdgeInsets.all(16),children:[IrkopSectionHeader(eyebrow:'Perangkat',title:'Device & Slot',subtitle:'Kelola perangkat bisnis.',icon:Icons.devices_outlined,action:'Tambah',onAction:add),if(s.connectionState!=ConnectionState.done)const Center(child:Padding(padding:EdgeInsets.all(30),child:CircularProgressIndicator())),...((s.data??const <DeviceRecord>[]).map((x)=>Card(child:SwitchListTile(value:x.active,onChanged:(v)async{await r.active(id:x.id,businessId:widget.businessId!,value:v);await refresh();},title:Text(x.name),subtitle:Text(x.code)))))])));}
